def add_range(ranges: list[list[int]], new: list[int]) -> list[list[int]]:
    start, end = new
    before, after = [], []
    for s, e in ranges:
        if e < start:
            before.append([s, e])            # ends before `new` starts
        elif s > end:
            after.append([s, e])             # starts after `new` ends
        else:                                # overlaps or touches: absorb it
            start, end = min(start, s), max(end, e)
    return before + [[start, end]] + after
